// main.py posts one of these after every clicker press (n8n.webhook_url in config.yaml):
// {heard, intent, object, understood_by: qwen|rules, qwen_ms, answer, point_at, action, laser_err_cm,
//   online, record_transcribe_s, ask_s, click_to_laser_s, stt_ms}
const q = $json.body;
const problems = [];
if (!q.heard) problems.push('heard nothing: mic level, or the visitor spoke before the click?');
if (q.answer === "I can tell you where things are, what happened to them, or what changed.")
  problems.push(q.online ? 'Grok gave no answer' : 'offline, so an open question got the canned reply');
if ((q.click_to_laser_s || 0) > 3) problems.push(`click to laser took ${q.click_to_laser_s} s (target 3 s)`);
if ((q.qwen_ms || 0) > 1000) problems.push(`Qwen took ${q.qwen_ms} ms`);
if (q.laser_err_cm != null && q.laser_err_cm > 3) problems.push(`laser landed ${q.laser_err_cm} cm off`);
const what = q.object ? `${q.intent} ${q.object}` : (q.intent || '-');
return [{ json: {
  summary: `"${q.heard}" -> ${what} (${q.understood_by || '-'}) -> "${q.answer}"`
           + (q.click_to_laser_s != null ? ` in ${q.click_to_laser_s} s` : ''),
  ok: problems.length === 0, problems, ...q } }];

// /state is {state: world.state_json(), last_answer, server_t}. Hidden objects (INSIDE, UNDER, HELD)
// are normal during a demo; a lost track, a stalled detector, no Qwen or no internet are worth a look.
const s = $('Get room state').first().json.state || {};
const problems = [];
if ($json.error) problems.push('Qwen (llama-server) not answering: questions fall back to the rule parser. Run scripts/qwen_server.sh');
if ((s.fps || 0) < 10) problems.push(`perception at ${s.fps || 0} fps (want 10+): is the detector running?`);
if (!s.online) problems.push('rig is offline: open questions get the canned reply, voice is Piper');
const lost = (s.entities || []).filter(e => e.status === 'UNKNOWN').map(e => e.name);
if (lost.length) problems.push(`lost track of: ${lost.join(', ')}`);
const gone = (s.entities || []).filter(e => e.status === 'GONE').map(e => `${e.name} (${e.edge || 'edge'})`);
if (gone.length) problems.push(`left the table: ${gone.join(', ')}`);
return [{ json: { ok: problems.length === 0, problems, fps: s.fps, online: s.online, qwen: !$json.error,
                  checked: new Date().toISOString() } }];
